# -*- coding: utf-8 -*-
from common import md, esc, cq, verse_card, VER, DATE, CREEDS
def index(eps):
    b=['<div class="intro2 glass reveal"><p>'+md("四福音书是神为祂教会留下的、关于祂儿子耶稣基督的**四重见证**。本站先从**整本圣经与圣约**看福音书的位置，再走进**时间、故事与地图**，然后逐卷深读马太、马可、路加、约翰（背景、为什么写、写了什么、圣经神学、==圣约神学==、!!难点!!、信条对照、应用），再用**对观与受难周**、**教义主题**、**三大信经**与**记忆自测**把它们收拢。")+'</p></div>']
    b.append('<h2 id="i1">📚 四卷福音书</h2><div class="bgrid g4">'+"".join(f'<a class="bk glass reveal" href="{e["fn"]}" style="--gc:{e["col"]}"><span class="bi">{e["ic"]}</span><b>{e["n"]}</b><small>{e["port"]} · {e["kw"]} · {e["ch"]} 章</small></a>' for e in eps)+'</div>')
    rows="".join(f'<tr style="--gc:{e["col"]}"><td><a href="{e["fn"]}">{e["ic"]} {e["n"]}</a></td><td>{esc(e["port"])}</td><td><b class="kwt">{e["kw"]}</b></td><td>{md("{{"+e["kv"]+"}}")}</td><td>{esc(e["aud"])}</td><td>{md(e["date"])}</td><td>{esc(e["sym"])}</td></tr>' for e in eps)
    b.append(f'<div class="tbl"><table><thead><tr><th>书卷</th><th>耶稣的画像</th><th>钥字</th><th>钥节</th><th>读者</th><th>时间</th><th>传统象征</th></tr></thead><tbody>{rows}</tbody></table></div>')
    b.append('<h2 id="i2">🧭 学习路线</h2><div class="flow">'+"".join(f'<a class="fstep" href="{h}"><span class="n">{k+1}</span>{t}</a>'+('<i class="farr">➜</i>' if k<6 else '') for k,(h,t) in enumerate([("bible.html","整本圣经与圣约：福音书在救赎历史中的位置"),("history.html","时间线、故事线、地图与文化"),("mark.html","逐卷深读（建议先读马可）"),("synoptic.html","对观问题、福音和谐、受难周"),("doctrine.html","十大教义主题 · 信条对照"),("creeds.html","三大信经背诵与比较"),("memory.html","口诀、记忆卡、小考")]))+'</div>')
    br="".join(f'<li style="--gc:{e["col"]}"><a href="{e["fn"]}" class="mt-b">{e["ic"]} {e["n"]} · <b>{e["kw"]}</b></a><ul>'+"".join(f'<li><span>{t}</span></li>' for _,t,_ in e["ol"][:4])+'</ul></li>' for e in eps)
    b.append(f'<h2 id="i3">🌳 四福音总思维导图</h2><div class="mtree glass reveal"><div class="mt-root">✝️ 一位基督 · 四重见证</div><ul class="mt-l1">{br}</ul></div>')
    b.append('<h2 id="i4">✨ 一节总纲</h2>'+verse_card("约20:31")+'<p class="note">'+md("约翰的目的句也是四卷福音书共同的目的：认识耶稣是谁（**基督、神的儿子**），并因信祂的名得生命。")+'</p>')
    b.append('<h2 id="i5">🎨 颜色与标记</h2><div class="tbl"><table><tbody><tr><td><b class="key">金色粗体</b></td><td>重点：必须掌握的核心教义与钥句</td></tr><tr><td><span class="hard">珊瑚红底</span></td><td>难点：历来争议或容易误解之处（附改革宗解答）</td></tr><tr><td><span class="cov">紫色下划线</span></td><td>圣约神学：恩典之约、应许、记号与印证</td></tr><tr><td><span class="term">青色虚线</span></td><td>术语</td></tr><tr><td><button type="button" class="vs" data-t="神爱世人，甚至将他的独生子赐给他们，叫一切信他的，不致灭亡，反得永生。">约3:16</button></td><td>经文出处，点按弹出和合本经文</td></tr><tr><td>📘📗📕🎙️</td><td>海德堡要理问答 · 比利时信条 · 多特信经 · CCI 讲道（CCI 中文，逐字）</td></tr><tr><td>📙</td><td>威斯敏斯特标准（RTF-USA 中译，比较用）</td></tr></tbody></table></div>')
    return "".join(b)
def sources(stats):
    S=[("信经与信条（逐字引用来源）",[("CCI 使徒信经",CREEDS["apostles"]["url"]),("CCI 尼西亚信经",CREEDS["nicene"]["url"]),("CCI 亚他那修信经",CREEDS["athanasian"]["url"]),("CCI 海德堡要理问答","https://ccifellowship.org/books/book-of-praise/confessions/heidelberg-catechism"),("CCI 比利时信条","https://ccifellowship.org/books/book-of-praise/confessions/the-belgic-confession"),("CCI 多特信经","https://ccifellowship.org/books/book-of-praise/confessions/canons-of-dort")]),
       ("CCI 讲道（本站逐字节录）",[("神的道（约1:1-18）","https://ccifellowship.org/sermons/text/99"),("法利赛人与税吏（路18:9-14）","https://ccifellowship.org/sermons/text/100"),("用属世的钱财结交属天的朋友（路16:9）","https://ccifellowship.org/sermons/text/102"),("海德堡要理问答第 48 主日：神国的到来","https://ccifellowship.org/sermons/heidelberg-catechism/lord-day-48"),("耶稣基督是唯一的救主（徒4:12，延伸）","https://ccifellowship.org/sermons/text/98")]),
       ("经文与地图",[("和合本（CUV）经文：getBible API","https://api.getbible.net/v2/cus/40/1.json"),("Natural Earth 地图数据（公有领域）","https://www.naturalearthdata.com/")]),
       ("改革宗参考（未直接引用原文，仅供延伸）",[("ccreformed.org","https://www.ccreformed.org/"),("reformedbeginner.net","https://reformedbeginner.net/"),("加拿大改革宗教会 CanRC","https://canrc.org/"),("北美联合改革宗教会 URCNA","https://www.urcna.org/"),("传承改革宗教会 HRC","https://heritagereformed.com/"),("基督教改革宗教会 PRCA","https://prca.org/"),("正统长老会 OPC","https://opc.org/"),("Mid-America Reformed Seminary","https://www.midamerica.edu/"),("Canadian Reformed Theological Seminary","https://crts.ca/"),("Puritan Reformed Theological Seminary","https://prts.edu/")]),
       ("威斯敏斯特标准（比较用）",[("RTF-USA 简体中文译本（贾少彬 译），本站引文取自其数据","https://rtf-usa.org/")])]
    b=['<h2 id="s1">🔖 来源</h2>']
    for k,(t,L) in enumerate(S): b.append(f'<h3 id="s1-{k}">{t}</h3><ul class="src">'+"".join(f'<li><a href="{u}" target="_blank" rel="noopener">{n}</a></li>' for n,u in L)+'</ul>')
    b.append('<h2 id="s2">✅ 校验结果（构建时自动生成）</h2><div class="tbl"><table><tbody>'+"".join(f'<tr><td><b>{k}</b></td><td>{v}</td></tr>' for k,v in stats)+'</tbody></table></div>')
    b.append('<h2 id="s3">⚠️ 说明与局限</h2><ul class="src"><li>信条与讲道引文逐字取自 ccifellowship.org 的中文译本；其他译本措辞可能不同。</li><li>作者、年代、写作地点（如马太写于巴勒斯坦或安提阿）列出改革宗与保守福音派常见观点，学界有其他看法。</li><li>地图路线为依据福音书地名连成的示意线，不代表精确的古代道路；以马忤斯、格拉森等地点位置有不同说法；耶路撒冷图为非比例示意。</li><li>独有材料比例为常被引用的近似统计。</li><li>讲解、口诀与图表为本站学习整理，不是任何教会的正式文件；权威在圣经，其次在教会公认的信条。</li></ul>')
    b.append(f'<h2 id="s4">🗂️ 版本</h2><div class="tbl"><table><thead><tr><th>版本</th><th>日期</th><th>说明</th></tr></thead><tbody><tr><td>{VER}</td><td>{DATE}（台北时间）</td><td>首次发布：四福音书逐卷深读、整本圣经与圣约、时间线与巴勒斯坦地图、对观与受难周、教义主题、三大信经背诵与比较、记忆自测。</td></tr></tbody></table></div>')
    return "".join(b)
